    assert regs.CFG_REG.LOOPBACK.read() == 0x1
    regs.CFG_REG.LOOPBACK.write(0)
    regs.AXI_DATA1_REG.DATA1.write(0xdeadbeef)
    assert regs.AXI_DATA1_REG.DATA1.read() == 0xdeadbeef
    regs.AXI_DATA1_REG.DATA1.write(0)
