    regs.CFG_REG.SYNC_DIS.write(0x1)
    regs.CFG_REG.LOOPBACK.write(0x1)
    regs.AXI_DATA1_REG.DATA1.write(0xabcd)
    regs.AXI_DATA2_REG.DATA2.write(0xabcd)
    regs.ADDR_REG.ADDR.write(0xf)
    regs.TX_RX_DDR_REG.TX_DELAY.write(0x1ff)
    regs.TX_RX_DDR_REG.TX_CLK_BOOST.write(0x1)
