    assert regs.CFG_REG.CLK_PHA.read() == 0x1
    assert regs.CFG_REG.AUTO_PHA.read() == 0x1
    assert regs.CFG_REG.SYNC_DIS.read() == 0x1
    assert regs.CFG_REG.LOOPBACK.read() == 0x1
    assert regs.AXI_DATA1_REG.DATA1.read() == 0xabcd
    assert regs.AXI_DATA2_REG.DATA2.read() == 0xabcd
    assert regs.ADDR_REG.ADDR.read() == 0xf
    assert regs.TX_RX_DDR_REG.TX_DELAY.read() == 0x1ff
